import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def has_roots_mod_p(f, p):
    # Compute the Legendre symbol
    legendre_symbol = pow(f.subs('x', 2), (p - 1) // 2, p)
    return legendre_symbol == 1

# Check for each odd prime p > 3
for p in range(7, 100, 2):  # Start from 7, as 5 is not an odd prime > 3
    if is_prime(p):
        f = sympy.sympify('x**2 + 3*x + 3')
        if has_roots_mod_p(f, p):
            print(f'p = {p} has roots mod {p}')
        else:
            print(f'p = {p} does not have roots mod {p}')

